import sys

class Employee:
    def __init__(self):
        self.salary = 100
        self.hours_worked = 0

    def getInfo(self, salary, hours_worked):
        self.salary = salary
        self.hours_worked = hours_worked

    def AddSal(self):
        if self.salary < 500:
            self.salary += 100

    def AddWorkSal(self, amount):
        self.salary += amount

employee = Employee()
employee_id, option = map(int, sys.stdin.readline().split())

if option == 1:
    salary, hours_worked = map(int, sys.stdin.readline().split())
    employee.getInfo(salary, hours_worked)
    print(str(employee.salary) + '$')
elif option == 2:
    employee.AddSal()
    print(str(employee.salary) + '$')
elif option == 3:
    amount = int(sys.stdin.readline().strip())
    employee.AddWorkSal(amount)
    print(str(employee.salary) + '$')
